import pytest

from cynthus.messaging.common.signal.action_type import SignalActionType
from cynthus.messaging.common.signal.base import SignalBase
from cynthus.messaging.common.signal.domain_type import SignalDomainType


def make_signal(**attributes):
    return type('Signal', (SignalBase,), attributes)


def full(**overrides):
    return {'domain': SignalDomainType.MEAL, 'aggregate': 'plan', 'action': SignalActionType.CREATED, **overrides}


def test_default_visibility_is_public():
    assert SignalBase.visibility == 'public'


def test_name_joins_visibility_domain_aggregate_and_action():
    assert make_signal(**full()).name == 'public.meal.plan.created'


def test_name_uses_an_overridden_visibility():
    assert make_signal(**full(visibility='private')).name == 'private.meal.plan.created'


def test_name_is_computed_on_the_class_not_the_instance_state():
    signal = make_signal(**full(aggregate='vote', action=SignalActionType.CAST))

    assert signal.name == 'public.meal.vote.cast'


def test_name_cannot_be_assigned():
    signal = make_signal(**full())

    with pytest.raises(AttributeError):
        signal.name = 'x'


@pytest.mark.parametrize('missing', ['domain', 'aggregate', 'action'])
def test_a_concrete_signal_must_define_every_component(missing):
    attributes = full()
    del attributes[missing]

    with pytest.raises(TypeError, match=missing):
        make_signal(**attributes)


def test_all_missing_components_are_listed_together():
    with pytest.raises(TypeError) as error:
        make_signal()

    message = str(error.value)

    assert 'domain' in message and 'aggregate' in message and 'action' in message
    assert 'Signal' in message


def test_abstract_signals_skip_the_component_check():
    class Intermediate(SignalBase, abstract=True):
        domain = SignalDomainType.MEAL

    assert Intermediate.domain is SignalDomainType.MEAL


def test_components_can_be_inherited_from_an_abstract_parent():
    class Intermediate(SignalBase, abstract=True):
        domain = SignalDomainType.MEAL
        aggregate = 'tag'

    class Concrete(Intermediate):
        action = SignalActionType.DELETED

    assert Concrete.name == 'public.meal.tag.deleted'


def test_a_child_of_a_concrete_signal_inherits_all_components():
    parent = make_signal(**full())

    class Child(parent):
        pass

    assert Child.name == parent.name


def test_unknown_class_keywords_are_rejected():
    with pytest.raises(TypeError):
        class Bad(SignalBase, abstract=True, unexpected=True):
            pass
